export function parse(s) {
  let scheme = null, authority = null, query = null, fragment = null
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  if (s.startsWith('//')) {
    s = s.slice(2)
    const e = s.search(/\//)
    if (e >= 0) { authority = s.slice(0, e); s = s.slice(e) } else { authority = s; s = '' }
  }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const c = a.indexOf(':', rb + 1)
  let host = a, port = null
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const bad = (s) => s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(u) {
  const scheme = u.scheme === null ? null : lower(u.scheme)
  let ui = null, host = null, port = null
  if (u.authority !== null) ({ userinfo: ui, host, port } = splitAuthority(u.authority))
  const checks = [['path', u.path], ['userinfo', ui], ['host', host], ['query', u.query], ['fragment', u.fragment]]
  for (const [name, v] of checks) if (bad(v)) return { error: `the ${name} has a truncated percent-encoding` }
  let out = ''
  if (scheme !== null) out += scheme + ':'
  let path = removeDots(pct(u.path))
  if (u.authority !== null) {
    out += '//'
    if (ui !== null) out += pct(ui) + '@'
    out += lower(pct(host))
    if (port !== null && port !== '' && port !== DEFAULT[scheme]) out += ':' + port
    if (path === '') path = '/'
  }
  out += path
  if (u.query !== null) out += '?' + pct(u.query)
  if (u.fragment !== null) out += '#' + pct(u.fragment)
  return { value: out }
}

export function resolve(base, ref) {
  const r = parse(ref)
  const t = { scheme: null, authority: null, path: '', query: null, fragment: r.fragment }
  if (r.scheme !== null) {
    Object.assign(t, r, { path: removeDots(r.path) })
  } else if (r.authority !== null) {
    Object.assign(t, r, { scheme: base.scheme, path: removeDots(r.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (r.path === '') {
      t.path = base.path
      t.query = r.query !== null ? r.query : base.query
    } else {
      if (r.path.startsWith('/')) t.path = removeDots(r.path)
      else {
        let merged
        if (base.authority !== null && base.path === '') merged = '/' + r.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i >= 0 ? base.path.slice(0, i + 1) + r.path : r.path
        }
        t.path = removeDots(merged)
      }
      t.query = r.query
    }
  }
  return t
}
