import { readFileSync } from 'node:fs'
import { parse, normalize, resolve } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  console.error('error: usage: cli.js normalize|resolve')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  let u
  if (mode === 'normalize') u = parse(lines[i])
  else {
    const sp = lines[i].indexOf(' ')
    if (sp < 0) fail(n, 'expected a base and a reference')
    const base = parse(lines[i].slice(0, sp))
    if (base.scheme === null) fail(n, 'the base has no scheme')
    u = resolve(base, lines[i].slice(sp + 1))
  }
  const r = normalize(u)
  if (r.error) fail(n, r.error)
  out.push(r.value)
}
process.stdout.write(out.map((l) => l + '\n').join(''))

function fail(n, msg) {
  console.error(`error: line ${n}: ${msg}`)
  process.exit(2)
}
EOF
