{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(text, field, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(text)
}

function makeBucket(name, cap, refill, per) {
  return {
    name,
    fresh: () => ({ units: cap * per, last: null }),
    advance(s, t) {
      if (s.last !== null) {
        s.units += refill * (t - s.last)
        if (s.units > cap * per) s.units = cap * per
      }
      s.last = t
    },
    ask: (s) => s.units >= per,
    record: (s) => { s.units -= per },
  }
}

function makeWindow(name, limit, span) {
  return {
    name,
    fresh: () => ({ ticks: [], head: 0 }),
    advance(s, t) {
      while (s.head < s.ticks.length && s.ticks[s.head] <= t - span) s.head++
    },
    ask: (s) => BigInt(s.ticks.length - s.head) < limit,
    record: (s, t) => { s.ticks.push(t) },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) throw new Fail(`unknown directive ${d}`)
      if (d !== 'event' && events.length) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (w.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        let p
        if (d === 'bucket') {
          const c = num(w[2], 'capacity', 1), r = num(w[3], 'refill', 0), per = num(w[4], 'per', 1)
          p = () => makeBucket(w[1], c, r, per)
        } else {
          const l = num(w[2], 'limit', 0), s = num(w[3], 'span', 1)
          p = () => makeWindow(w[1], l, s)
        }
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], p())
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        for (const p of w.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(w[1], w.slice(2).map((p) => policies.get(p)))
      } else {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const t = num(w[1], 'tick', 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && t < lastTick) throw new Fail(`tick ${t} is before tick ${lastTick}`)
        lastTick = t
        events.push([t, w[2]])
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

let result
try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const states = new Map()
  const out = []
  const stats = new Map()
  let ta = 0, td = 0
  for (const [t, key] of events) {
    let best = null
    for (const [prefix, ps] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, ps }
    }
    let denier = null
    if (best) {
      const sts = best.ps.map((p) => {
        let m = states.get(p)
        if (!m) states.set(p, (m = new Map()))
        let s = m.get(key)
        if (!s) m.set(key, (s = p.fresh()))
        p.advance(s, t)
        return s
      })
      for (let i = 0; i < sts.length; i++) {
        if (!best.ps[i].ask(sts[i])) { denier = best.ps[i].name; break }
      }
      if (denier === null) best.ps.forEach((p, i) => p.record(sts[i], t))
    }
    const st = stats.get(key) || (stats.set(key, { a: 0, d: 0 }), stats.get(key))
    if (denier === null) { st.a++; ta++ } else { st.d++; td++ }
    out.push(`${t} ${key} ${denier === null ? 'allow' : 'deny ' + denier}\n`)
  }
  if (mode === 'replay') result = out.join('')
  else {
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    result = keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') + `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
EOF
