    result = keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') + `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
