{"file_path":"src/sheet.js","content":"export function colIndex(letters) {
  return letters.length === 1
    ? letters.charCodeAt(0) - 64
    : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

// Returns {col,row,key} for a valid address word, else null.
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})(\d{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, key: letters + row }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const s = lines[i].replace(/^[ \t]+/, '')
    if (s === '' || s[0] === '#') continue
    const m = /^[^ \t]*/.exec(s)
    const word = m[0]
    const content = s.slice(word.length).replace(/^[ \t]+/, '')
    const a = parseAddr(word)
    if (!a) return { error: `error: line ${i + 1}: invalid cell address ${word}` }
    if (cells.has(a.key)) return { error: `error: line ${i + 1}: cell ${word} is declared twice` }
    cells.set(a.key, { addr: a, content })
  }
  return { cells }
}
"}

{"file_path":"src/eval.js","content":"import { parseAddr } from './sheet.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ err: e })
const isErr = (v) => typeof v === 'object' && v !== null
const E_DIV = err('#DIV/0!')
const E_REF = err('#REF!')
const E_VAL = err('#VALUE!')
const E_CYC = err('#CYCLE!')
const E_NAME = err('#NAME?')
const E_ERR = err('#ERR!')

// ---------- parser ----------
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('parse') }
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const cmpOps = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && cmpOps.includes(peek().v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { k: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', a: t.v }
    }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

// ---------- analysis ----------
function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  return out
}

// true when a range appears somewhere other than directly as a call argument
function misplaced(n, direct = false) {
  switch (n.k) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'neg': return misplaced(n.e)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function collectDeps(n, set) {
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(a.key, a); break }
    case 'range': {
      const cs = rangeCells(n)
      if (cs) for (const c of cs) set.set(keyOf(c.col, c.row), c)
      break
    }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'neg': collectDeps(n.e, set); break
    case 'call': for (const a of n.args) collectDeps(a, set); break
  }
}

function colName(c) {
  return c <= 26 ? String.fromCharCode(64 + c)
    : String.fromCharCode(65 + Math.floor((c - 27) / 26)) + String.fromCharCode(65 + ((c - 27) % 26))
}
const keyOf = (col, row) => colName(col) + row

function sortedCells(cells) {
  return [...cells.values()].sort((x, y) => x.addr.col - y.addr.col || x.addr.row - y.addr.row)
}

export function runDeps(cells) {
  let out = ''
  for (const cell of sortedCells(cells)) {
    let line = cell.addr.key + ':'
    if (cell.content[0] === '=') {
      const ast = parseFormula(cell.content.slice(1))
      if (ast) {
        const set = new Map()
        collectDeps(ast, set)
        const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of list) line += ' ' + keyOf(d.col, d.row)
      }
    }
    out += line + '\n'
  }
  return out
}

// ---------- evaluation ----------
function kindRank(v) { return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}
function toNum(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  if (typeof v === 'string') return E_VAL
  return v
}
const fin = (x) => (Number.isFinite(x) ? x : E_DIV)

export function runValues(cells) {
  const memo = new Map()
  const active = new Set()

  function cellValue(key) {
    const cell = cells.get(key)
    if (!cell) return 0
    if (memo.has(key)) return memo.get(key)
    if (active.has(key)) return E_CYC
    active.add(key)
    let v
    try { v = evalContent(cell.content) } finally { active.delete(key) }
    memo.set(key, v)
    return v
  }

  function evalContent(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast || misplaced(ast)) return E_ERR
      return ev(ast)
    }
    if (content === '') return 0
    if (/^-?\d+(\.\d+)?$/.test(content)) return Number(content)
    if (ERRS.includes(content)) return err(content)
    return content
  }

  function refValue(word) {
    const a = parseAddr(word)
    return a ? cellValue(a.key) : E_REF
  }

  function argValues(n) {
    if (n.k === 'range') {
      const cs = rangeCells(n)
      if (!cs) return [E_REF]
      return cs.map((c) => cellValue(keyOf(c.col, c.row)))
    }
    return [ev(n)]
  }

  function ev(n) {
    switch (n.k) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'ref': return refValue(n.a)
      case 'range': return E_ERR
      case 'neg': {
        const v = ev(n.e)
        if (isErr(v)) return v
        const x = toNum(v)
        if (isErr(x)) return x
        return n.op === '-' ? -x : x
      }
      case 'bin': return bin(n)
      case 'call': return call(n)
    }
    return E_ERR
  }

  function bin(n) {
    const l = ev(n.l), r = ev(n.r)
    if (isErr(l)) return l
    if (isErr(r)) return r
    const op = n.op
    if (['=', '<>', '<', '<=', '>', '>='].includes(op)) {
      const kl = kindRank(l), kr = kindRank(r)
      let d
      if (kl !== kr) d = kl - kr
      else if (kl === 0) d = l < r ? -1 : l > r ? 1 : 0
      else if (kl === 1) d = cpCompare(l, r)
      else d = Number(l) - Number(r)
      switch (op) {
        case '=': return d === 0
        case '<>': return d !== 0
        case '<': return d < 0
        case '<=': return d <= 0
        case '>': return d > 0
        default: return d >= 0
      }
    }
    const x = toNum(l)
    if (isErr(x)) return x
    const y = toNum(r)
    if (isErr(y)) return y
    switch (op) {
      case '+': return fin(x + y)
      case '-': return fin(x - y)
      case '*': return fin(x * y)
      case '/': return y === 0 ? E_DIV : fin(x / y)
      default: return fin(Math.pow(x, y))
    }
  }

  function call(n) {
    const name = n.name
    const cnt = n.args.length
    if (name === 'IF') {
      if (cnt !== 3) return E_ERR
      const c = argValues(n.args[0])[0]
      if (isErr(c)) return c
      if (typeof c === 'string') return E_VAL
      const truth = typeof c === 'boolean' ? c : c !== 0
      return argValues(n.args[truth ? 1 : 2])[0]
    }
    if (name === 'ABS') {
      if (cnt !== 1) return E_ERR
      const v = argValues(n.args[0])[0]
      if (isErr(v)) return v
      const x = toNum(v)
      return isErr(x) ? x : Math.abs(x)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return E_NAME
    if (cnt < 1) return E_ERR
    const vals = []
    for (const a of n.args) for (const v of argValues(a)) vals.push(v)
    for (const v of vals) if (isErr(v)) return v
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (isErr(x)) return x
      nums.push(x)
    }
    if (name === 'SUM') return fin(nums.reduce((s, x) => s + x, 0))
    if (name === 'MIN') return Math.min(...nums)
    if (name === 'MAX') return Math.max(...nums)
    return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }

  function fmt(v) {
    if (isErr(v)) return v.err
    if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
    if (typeof v === 'number') return String(Number(v.toPrecision(10)))
    return v
  }

  let out = ''
  for (const cell of sortedCells(cells)) out += `${cell.addr.key}=${fmt(cellValue(cell.addr.key))}\n`
  return out
}
"}

