{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {}

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, msg) => { throw new ScanError(`${l}:${c}: ${msg}`) }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col, start = i
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) fail(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      adv()
      tokens.push({ l: sl, c: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isLetter(c) || c === '_') {
      while (i < n && isIdent(cs[i])) adv()
      const s = cs.slice(start, i).join('')
      tokens.push({ l: sl, c: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let ok = true
      // consume a run of digits (per predicate) with single underscores between digits
      const run = (pred) => {
        let any = false
        while (i < n) {
          if (pred(cs[i])) { adv(); any = true }
          else if (cs[i] === '_' && any && pred(cs[i - 1]) && pred(cs[i + 1])) adv()
          else break
        }
        return any
      }
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        adv(); adv()
        const pred = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        ok = run(pred)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1], b = cs[i + 2]
          if (isDigit(a)) { adv(); run(isDigit) }
          else if ((a === '+' || a === '-') && isDigit(b)) { adv(); adv(); run(isDigit) }
        }
      }
      if (!ok || isIdent(cs[i])) {
        while (i < n && isIdent(cs[i])) adv()
        fail(sl, sc, `invalid number ${cs.slice(start, i).join('')}`)
      }
      tokens.push({ l: sl, c: sc, kind: 'number', body: cs.slice(start, i).join('') })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') fail(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) fail(sl, sc, 'unterminated string')
        const e = cs[i]
        const bad = () => fail(bl, bc, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { adv(); v += simple[e] }
        else if (e === 'x') {
          if (!(isHex(cs[i + 1]) && isHex(cs[i + 2]))) bad()
          adv(); const h = adv() + adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else if (e === 'u') {
          if (cs[i + 1] !== '{') bad()
          let j = i + 2, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) bad()
          while (i <= j) adv()
          v += String.fromCodePoint(cp)
        } else bad()
      }
      tokens.push({ l: sl, c: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.includes(two)) {
      adv(); adv()
      tokens.push({ l: sl, c: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ l: sl, c: sc, kind: 'punct', body: c })
      continue
    }
    fail(sl, sc, `unexpected character ${c}`)
