      if (regions) out.push(`stable ${end - pos}`)
      else out.push(...base.slice(pos, end))
    }
  }
  let k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const rs = group[0].bs
    let re = group[0].be
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = (who, lines) => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseLines
      const s = Math.min(...cs.map(c => c.bs))
      const e = Math.max(...cs.map(c => c.be))
      const ss = Math.min(...cs.map(c => c.ss)) - (s - rs)
      const se = Math.max(...cs.map(c => c.se)) + (re - e)
      return lines.slice(ss, se)
