{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { evaluateAll, depsOf, formatValue } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let cells
try {
  cells = parseSheet(readFileSync(0, 'utf8'))
} catch (e) {
  if (e instanceof SheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

const keys = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
if (args[0] === 'values') {
  const values = evaluateAll(cells)
  for (const c of keys) out += `${c.addr}=${formatValue(values.get(c.addr))}\n`
} else {
  for (const c of keys) out += `${c.addr}:${depsOf(c).map((a) => ' ' + a).join('')}\n`
}
process.stdout.write(out)
"}

{"file_path":"src/sheet.js","content":"export class SheetError extends Error {}

export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, addr: letters + row }
}

export function colName(col) {
  return col <= 26
    ? String.fromCharCode(64 + col)
    : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^[^ \t]*/.exec(line)
    const word = m[0]
    let rest = line.slice(word.length)
    rest = rest.replace(/^[ \t]+/, '')
    const a = parseAddress(word)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${word.toUpperCase()}`)
    if (cells.has(a.addr)) throw new SheetError(`error: line ${i + 1}: cell ${a.addr} is declared twice`)
    cells.set(a.addr, { addr: a.addr, col: a.col, row: a.row, content: rest })
  })
  return cells
}
"}

{"file_path":"src/eval.js","content":"import { parseAddress, colName } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'err', v: code })
const num = (v) => ({ t: 'num', v })
const FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class ParseFail extends Error {}

// ---- tokenizer / parser ----
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0].toUpperCase() }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=^*/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    throw new ParseFail()
  }
  return toks
}

// returns { ast, misplaced } ; throws ParseFail
function parse(body) {
  const toks = tokenize(body)
  let p = 0
  let misplaced = false
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw new ParseFail() }

  function comparison() {
    let l = additive()
    while (peek() && peek().k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = multiplicative()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: multiplicative() }
    }
    return l
  }
  function multiplicative() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: power() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary(allowRange = false) {
    const t = toks[p]
    if (!t) fail()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = comparison()
        if (!isOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    // word
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { n: 'call', name: t.v, args }
    }
    if (isOp(':')) {
      p++
      const t2 = toks[p]
      if (!t2 || t2.k !== 'word') fail()
      p++
      if (isOp('(')) fail()
      const node = { n: 'range', a: t.v, b: t2.v }
      if (!allowRange) misplaced = true
      return node
    }
    if (t.v === 'TRUE') return { n: 'bool', v: true }
    if (t.v === 'FALSE') return { n: 'bool', v: false }
    return { n: 'ref', a: t.v }
  }
  // an argument: a range is fine only when it is the whole argument
  function arg() {
    const save = p
    const t = toks[p]
    if (t && t.k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':') {
      const r = primary(true)
      const nx = toks[p]
      if (nx && nx.k === 'op' && (nx.v === ',' || nx.v === ')')) return r
      // range followed by an operator: misplaced
      p = save
    }
    return comparison()
  }

  const ast = comparison()
  if (p !== toks.length) fail()
  return { ast, misplaced }
}

const parseCache = new Map()
function compile(cell) {
  if (cell.compiled !== undefined) return cell.compiled
  const c = cell.content
  let res
  if (c[0] === '=') {
    try { res = parse(c.slice(1)) } catch (e) { if (e instanceof ParseFail) res = null; else throw e }
  } else res = false
  cell.compiled = res
  return res
}

// ---- references ----
function rangeCells(a, b) {
  const x = parseAddress(a), y = parseAddress(b)
  if (!x || !y) return null
  const c0 = Math.min(x.col, y.col), c1 = Math.max(x.col, y.col)
  const r0 = Math.min(x.row, y.row), r1 = Math.max(x.row, y.row)
  return { c0, c1, r0, r1 }
}

function collectRefs(ast, set) {
  switch (ast.n) {
    case 'ref': { const a = parseAddress(ast.a); if (a) set.add(a.col * 1000 + a.row); break }
    case 'range': {
      const r = rangeCells(ast.a, ast.b)
      if (r) for (let c = r.c0; c <= r.c1; c++) for (let w = r.r0; w <= r.r1; w++) set.add(c * 1000 + w)
      break
    }
    case 'bin': collectRefs(ast.l, set); collectRefs(ast.r, set); break
    case 'un': collectRefs(ast.e, set); break
    case 'call': ast.args.forEach((x) => collectRefs(x, set)); break
  }
}

export function depsOf(cell) {
  const c = compile(cell)
  if (!c) return []
  const set = new Set()
  collectRefs(c.ast, set)
  return [...set].sort((a, b) => a - b).map((k) => colName(Math.floor(k / 1000)) + (k % 1000))
}

// ---- evaluation ----
export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()

  function cellValue(addr) {
    if (memo.has(addr)) return memo.get(addr)
    const cell = cells.get(addr)
    if (!cell) return num(0)
    if (busy.has(addr)) return err('#CYCLE!')
    busy.add(addr)
    const v = evalCell(cell)
    busy.delete(addr)
    memo.set(addr, v)
    return v
  }

  function evalCell(cell) {
    const c = cell.content
    if (c[0] === '=') {
      const compiled = compile(cell)
      if (!compiled || compiled.misplaced) return err('#ERR!')
      return evalNode(compiled.ast)
    }
    if (c === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
    if (ERRORS.includes(c)) return err(c)
    return { t: 'text', v: c }
  }

  const toNum = (x) => (x.t === 'num' ? x : x.t === 'bool' ? num(x.v ? 1 : 0) : err('#VALUE!'))
  const fin = (v) => (Number.isFinite(v) ? num(v) : err('#DIV/0!'))
  const rank = { num: 0, text: 1, bool: 2 }

  function evalNode(n) {
    switch (n.n) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': {
        const a = parseAddress(n.a)
        return a ? cellValue(a.addr) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const v = evalNode(n.e)
        if (v.t === 'err') return v
        const x = toNum(v)
        if (x.t === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': {
        const l = evalNode(n.l)
        const r = evalNode(n.r)
        if (l.t === 'err') return l
        if (r.t === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          let cmp
          if (l.t !== r.t) cmp = rank[l.t] - rank[r.t]
          else if (l.t === 'text') cmp = l.v === r.v ? 0 : cmpCodePoints(l.v, r.v)
          else {
            const a = l.t === 'bool' ? +l.v : l.v
            const b = r.t === 'bool' ? +r.v : r.v
            cmp = a < b ? -1 : a > b ? 1 : 0
          }
          const res = { '=': cmp === 0, '<>': cmp !== 0, '<': cmp < 0, '<=': cmp <= 0, '>': cmp > 0, '>=': cmp >= 0 }[n.op]
          return { t: 'bool', v: res }
        }
        const a = toNum(l), b = toNum(r)
        if (a.t === 'err') return a
        if (b.t === 'err') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          case '^': return fin(Math.pow(a.v, b.v))
        }
      }
      case 'call': return evalCall(n)
    }
    return err('#ERR!')
  }

  function cmpCodePoints(a, b) {
    const x = [...a], y = [...b]
    for (let i = 0; i < x.length && i < y.length; i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d < 0 ? -1 : 1
    }
    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
  }

  function evalCall(n) {
    const name = n.name
    if (!FUNCS.has(name)) return err('#NAME?')
    const argc = n.args.length
    if (name === 'IF') {
      if (argc !== 3) return err('#ERR!')
    } else if (name === 'ABS') {
      if (argc !== 1) return err('#ERR!')
    } else if (argc < 1) return err('#ERR!')

    if (name === 'IF' || name === 'ABS') {
      if (name === 'ABS') {
        if (n.args[0].n === 'range') return err('#ERR!')
        const v = evalNode(n.args[0])
        if (v.t === 'err') return v
        const x = toNum(v)
        return x.t === 'err' ? x : num(Math.abs(x.v))
      }
      if (n.args.some((a) => a.n === 'range')) return err('#ERR!')
      const c = evalNode(n.args[0])
      if (c.t === 'err') return c
      if (c.t === 'text') return err('#VALUE!')
      const truth = c.t === 'bool' ? c.v : c.v !== 0
      return evalNode(truth ? n.args[1] : n.args[2])
    }

    const vals = []
    for (const a of n.args) {
      if (a.n === 'range') {
        const r = rangeCells(a.a, a.b)
        if (!r) { vals.push(err('#REF!')); continue }
        for (let c = r.c0; c <= r.c1; c++)
          for (let w = r.r0; w <= r.r1; w++) vals.push(cellValue(colName(c) + w))
      } else vals.push(evalNode(a))
    }
    for (const v of vals) if (v.t === 'err') return v
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
