{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/
const uint = (s, field, least) => {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

const policies = new Map()
const routes = new Map()
const states = new Map() // key -> array of states
const stats = new Map()
const out = []
let started = false
let prev = null
let allowed = 0, denied = 0

function makeState(p, tick) {
  return p.type === 'bucket'
    ? { last: tick, tokens: p.cap * p.per }
    : { ticks: [] }
}
function advance(p, s, tick) {
  if (p.type === 'bucket') {
    const max = p.cap * p.per
    s.tokens += p.refill * (tick - s.last)
    if (s.tokens > max) s.tokens = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}
const ask = (p, s) => (p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.type === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

function handle(f) {
  const d = f[0]
  if (d === 'bucket' || d === 'window') {
    const n = d === 'bucket' ? 5 : 4
    if (f.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
    if (started) throw new Fail('declarations must come before the first event')
    if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
    let p
    if (d === 'bucket') p = { type: 'bucket', cap: uint(f[2], 'capacity', 1), refill: uint(f[3], 'refill', 0), per: uint(f[4], 'per', 1) }
    else p = { type: 'window', limit: uint(f[2], 'limit', 0), span: uint(f[3], 'span', 1) }
    if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
    p.name = f[1]
    policies.set(f[1], p)
  } else if (d === 'route') {
    if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
    if (started) throw new Fail('declarations must come before the first event')
    if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
    if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
    const list = []
    for (const n of f.slice(2)) {
      if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
      list.push(policies.get(n))
    }
    routes.set(f[1], list)
  } else if (d === 'event') {
    if (f.length !== 3) throw new Fail('expected event <tick> <key>')
    const tick = uint(f[1], 'tick', 0)
    const key = f[2]
    if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
    if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
    started = true
    prev = tick
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let refused = null
    if (best !== null) {
      const list = routes.get(best)
      const sk = best + '\0' + key
      if (!states.has(sk)) states.set(sk, list.map((p) => makeState(p, tick)))
      const ss = states.get(sk)
      list.forEach((p, i) => advance(p, ss[i], tick))
      for (let i = 0; i < list.length; i++) if (!ask(list[i], ss[i])) { refused = list[i]; break }
      if (!refused) list.forEach((p, i) => record(p, ss[i], tick))
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (refused) { st.d++; denied++; out.push(`${tick} ${key} deny ${refused.name}`) }
    else { st.a++; allowed++; out.push(`${tick} ${key} allow`) }
  } else {
    throw new Fail(`unknown directive ${d}`)
  }
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
try {
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try { handle(line.split(/\s+/)) } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

if (mode === 'replay') process.stdout.write(out.map((l) => l + '\n').join(''))
else {
