export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // per round: Map name -> votes
  const rounds = []
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  for (;;) {
    const votes = new Map([...continuing].map((n) => [n, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((n) => continuing.has(n))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const listing = [...votes].sort((a, b) => (a[1] === b[1] ? (a[0] < b[0] ? -1 : 1) : a[1] > b[1] ? -1 : 1))
    const round = { listing, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [n, v] of listing) if (v * 2n > active) return { rounds, winner: n }
    const min = listing[listing.length - 1][1]
    let tied = listing.filter(([, v]) => v === min).map(([n]) => n)
    while (tied.length > 1) {
      let narrowed = false
      for (const h of history) {
        const vs = tied.map((n) => h.get(n))
        const lo = vs.reduce((a, b) => (b < a ? b : a))
        if (vs.some((v) => v !== lo)) {
          tied = tied.filter((n) => h.get(n) === lo)
          narrowed = true
          break
        }
      }
      if (!narrowed) break
    }
    tied.sort()
    const out = tied[tied.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
